CREATE TABLE Application_Table (
    Application_ID INTEGER PRIMARY KEY,
    Name VARCHAR(255)
);

CREATE TABLE User_Table (
    ID INTEGER PRIMARY KEY,
    Username VARCHAR(255)
);

CREATE TABLE Channel_Table (
    Belonging_Application INTEGER NOT NULL,
    Channel_ID INTEGER PRIMARY KEY,
    Creation_Time DATETIME,
    Creator INTEGER NOT NULL,
    Is_Private BOOL,
    Status VARCHAR(255),
    FOREIGN KEY (Belonging_Application) REFERENCES Application_Table(Application_ID),
    FOREIGN KEY (Creator) REFERENCES User_Table(ID)
);

CREATE TABLE Channel_Event_Table (
    Channel_ID INTEGER NOT NULL,
    Event_ID INTEGER PRIMARY KEY,
    Event_Type VARCHAR(255),
    Payload_Content VARCHAR(255),
    Timestamp DATETIME,
    FOREIGN KEY (Channel_ID) REFERENCES Channel_Table(Channel_ID)
);
